"use client";

import { useEffect, useMemo, useState } from "react";
import { questions, sleRounds } from "@/lib/quiz-data";

type Phase = "lobby" | "question" | "sle" | "leaderboard";
type Player = { id: string; name: string; score: number; joinedAt: number };
type GameState = {
  phase: Phase;
  players: Player[];
  currentQuestion: number;
  revealed: boolean;
  answers: Record<string, { choice: number; correct: boolean }>;
  pendingSleIndex: number | null;
  timeLeft: number;
  gameCode: string;
  questionCount: number;
};

const letters = ["A", "B", "C", "D"];
const confettiColors = ["#f97316", "#2563eb", "#14b8a6", "#facc15", "#ef4444", "#0f172a"];

export default function HostPage() {
  const [game, setGame] = useState<GameState | null>(null);
  const [confetti, setConfetti] = useState<number[]>([]);
  const question = game ? questions[game.currentQuestion] : null;
  const sle = game ? sleRounds[game.pendingSleIndex ?? 0] : sleRounds[0];
  const rankedPlayers = useMemo(() => [...(game?.players ?? [])].sort((a, b) => b.score - a.score), [game?.players]);

  async function refresh() {
    const response = await fetch("/api/game", { cache: "no-store" });
    const nextGame = await response.json();
    setGame(nextGame);
  }

  async function hostAction(action: "start" | "reveal" | "next" | "reset") {
    const response = await fetch("/api/host", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ action })
    });
    const nextGame = await response.json();
    setGame(nextGame);
    if (nextGame.phase === "leaderboard") launchConfetti();
  }

  function launchConfetti() {
    setConfetti(Array.from({ length: 120 }, (_, index) => index));
    window.setTimeout(() => setConfetti([]), 6200);
  }

  useEffect(() => {
    refresh();
    const id = window.setInterval(refresh, 650);
    return () => window.clearInterval(id);
  }, []);

  useEffect(() => {
    function shortcuts(event: KeyboardEvent) {
      if (!game) return;
      if (event.code === "Space" && game.phase === "question") {
        event.preventDefault();
        hostAction(game.revealed ? "next" : "reveal");
      }
    }

    window.addEventListener("keydown", shortcuts);
    return () => window.removeEventListener("keydown", shortcuts);
  }, [game]);

  if (!game) return <main className="app"><section className="card center"><h2>Loading...</h2></section></main>;

  return (
    <main className="app host-app">
      {game.phase === "lobby" && (
        <section className="card host-lobby screen-pop">
          <div className="topbar">
            <span className="pill">Host Screen</span>
            <button className="btn ghost" onClick={() => hostAction("reset")}>Reset</button>
          </div>
          <div className="host-hero-grid">
            <div className="stack">
              <span className="eyebrow">Queen of Apostles</span>
              <h1>How Well Do You Know <span>Aadit?</span></h1>
              <p className="lede">Classmates join on their iPads with the code below. Keep this screen on the projector.</p>
              <button className="btn primary start-button" onClick={() => hostAction("start")}>Start Game</button>
            </div>
            <div className="code-card">
              <p>Class Code</p>
              <strong>{game.gameCode}</strong>
              <span>{game.players.length} joined</span>
            </div>
          </div>
          <div className="player-list host-player-list">
            {game.players.length ? game.players.map((player) => <div className="player-chip" key={player.id}>{player.name}</div>) : <p className="tiny">Waiting for players...</p>}
          </div>
        </section>
      )}

      {game.phase === "question" && question && (
        <section className="card question-card screen-pop">
          <div className="topbar">
            <span className="pill">{question.round}</span>
            <span className="pill">Question {game.currentQuestion + 1} / {game.questionCount}</span>
            <span className={`timer-pill ${game.timeLeft <= 5 && !game.revealed ? "urgent" : ""}`}>{game.revealed ? "Reveal" : `${game.timeLeft}s`}</span>
          </div>
          <div className="question-text"><h2>{question.text}</h2></div>
          <div className="answers">
            {question.answers.map((answer, index) => (
              <div
                className={`answer ${letters[index].toLowerCase()} ${game.revealed && index === question.correct ? "correct" : ""} ${game.revealed && index !== question.correct ? "dim" : ""}`}
                key={answer}
              >
                <span className="letter">{letters[index]}</span>
                <span>{answer}</span>
              </div>
            ))}
          </div>
          <div className="status-panel">
            <div className="stat"><strong>{Object.keys(game.answers).length}</strong>Answered</div>
            <div className="stat"><strong>{game.players.length}</strong>Players</div>
            <div className="stat"><strong>+1000</strong>Max Points</div>
          </div>
          {game.revealed && <div className="story">{question.story}</div>}
          <div className="button-row">
            {!game.revealed && <button className="btn coral" onClick={() => hostAction("reveal")}>Reveal Correct Answer</button>}
            {game.revealed && <button className="btn primary" onClick={() => hostAction("next")}>Next</button>}
          </div>
        </section>
      )}

      {game.phase === "sle" && (
        <section className="card screen-pop">
          <div className="stack">
            <div className="eyebrow">SLE Reveal Card</div>
            <div className="sle-card">
              <div className="sle-badge"><span>{sle.title}</span></div>
              <div className="sle-notes">
                <div className="note"><b>My Definition</b>{sle.definition}</div>
                <div className="note"><b>My Claim</b>{sle.claim}</div>
                <div className="note"><b>My Evidence</b>{sle.evidence}</div>
              </div>
            </div>
            <div className="button-row"><button className="btn primary" onClick={() => hostAction("next")}>Continue Quiz</button></div>
          </div>
        </section>
      )}

      {game.phase === "leaderboard" && (
        <section className="card center screen-pop">
          <div className="stack">
            <div className="eyebrow">Final Leaderboard</div>
            <h2>Top 3 Aadit Experts</h2>
            <div className="leaderboard">
              {rankedPlayers.slice(0, 3).map((player, index) => (
                <div className="rank" key={player.id}>
                  <span>#{index + 1}</span>
                  <span>{player.name}</span>
                  <span>{player.score}</span>
                </div>
              ))}
            </div>
            <div className="button-row"><button className="btn primary" onClick={() => hostAction("reset")}>Reset for Another Round</button></div>
          </div>
        </section>
      )}

      <div className="confetti" aria-hidden="true">
        {confetti.map((piece) => (
          <i
            key={piece}
            style={{
              left: `${Math.random() * 100}%`,
              background: confettiColors[piece % confettiColors.length],
              animationDuration: `${2.4 + Math.random() * 2.8}s`,
              animationDelay: `${Math.random() * 0.8}s`
            }}
          />
        ))}
      </div>
    </main>
  );
}
